# Run from repository root. Optional argument: a staging directory.
source("R/pns_core.R", encoding="UTF-8")
args <- commandArgs(trailingOnly=TRUE)
stage <- if(length(args)) args[1] else file.path(pns_cache(),"release")
dir.create(stage,recursive=TRUE,showWarnings=FALSE)
jobs <- lapply(c(2013,2019),analyze_year)
x <- do.call(rbind,lapply(jobs,`[[`,"results"))
stopifnot(!anyDuplicated(x[c("indicator","year","geo")]))
stopifnot(all(x$n_valid+x$n_missing==x$n_eligible))
write.csv(x,file.path(stage,"estimates.csv"),row.names=FALSE,na="",fileEncoding="UTF-8")
write.csv(make_contrasts(x),file.path(stage,"contrasts.csv"),row.names=FALSE,na="",fileEncoding="UTF-8")
for(locale in c("pt","en")) for(group in names(groups)) export_group(x,group,locale,file.path(stage,locale))
sources <- lapply(c(2013,2019),function(year) list(year=year,base_url=paste0("https://ftp.ibge.gov.br/PNS/",year,"/Microdados/"),sha256=as.list(file_hashes(source_files(year)))))
packages <- c("PNSIBGE","survey","readxl","writexl","digest","jsonlite","rmarkdown","ggplot2","knitr","readr","dplyr","tidyr","scales")
manifest <- list(schema_version=2,run_utc=format(Sys.time(),tz="UTC",usetz=TRUE),baseline_commit="90c90494493a56aae7a8670d8b59b35e191658cd",analysis_sha256=unname(file_hashes(file.path(pns_root(),"R","pns_core.R"))),sources=sources,design_checks=setNames(lapply(jobs,`[[`,"validation"),c("2013","2019")),ipca=jsonlite::fromJSON("data/ipca_reference.json"),R=R.version.string,packages=setNames(lapply(packages,function(p) as.character(packageVersion(p))),packages),estimates_rows=nrow(x),output_sha256=as.list(file_hashes(file.path(stage,c("estimates.csv","contrasts.csv")))))
jsonlite::write_json(manifest,file.path(stage,"analysis_manifest.json"),pretty=TRUE,auto_unbox=TRUE,digits=16)
capture.output(sessionInfo(),file=file.path(stage,"sessionInfo.txt"))
message("Validated analysis staged at ",normalizePath(stage,winslash="/"))
